RODUCT_NAME": "IVR", "ROW_TEMPLATE": [{"LINK": "<dateLinkFunctionIfReq>", "DISPLAY": "C1"}, {"DISPLAY": "C2"}, {"DISPLAY": "C3"}, {"DISPLAY": "C4"}, {"DISPLAY": "C5"}, {"DISPLAY": "C6"}, {"DISPLAY": "C7"}, {"DISPLAY": "C8"}], "REPORT_HEADING": "Snap Shot"}'::jsonb);
