E, ''HH24'')", "M": "SELECT TO_CHAR(GEN_TIME, ''YYYY-MM-DD'') AS C1, COALESCE(SUM(CASE WHEN EVR_CAUSE = 1 THEN COUNT ELSE 0 END), 0) AS C2, COALESCE(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0) AS C3, COALESCE(SUM(CASE WHEN EVR_CAUSE = 13 THEN COUNT ELSE 0 END), 0) AS C4, COALESCE(SUM(CASE WHEN EVR_CAUSE = 4 THEN COUNT ELSE 0 END), 0) AS C5, COALESCE(SUM(CASE WHEN EVR_CAUSE = 5 THEN COUNT ELSE 0 END), 0) AS C6, COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END), 0) AS C7, CASE WHEN COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN COUNT ELSE 0 END), 0) = 0 THEN 0 ELSE ROUND(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END)::numeric / NULLIF(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0), 2) END AS C8 FROM IVR_MIS_CUMULATIVE WHERE GEN_TIME BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND ((''_$ShortCodeName$_'' != ''-1'' AND SHORT_CODE = ''_$ShortCodeName$_'') OR ''_$ShortCodeName$_'' = ''-1'') GROUP BY TO_CHAR(GEN_TIME, ''YYYY-MM-DD'') ORDER BY TO_CHAR(GEN_TIME, ''YYYY-MM-DD'')", "Y": "SELECT TO_CHAR(GEN_TIME, ''Month'') AS C1, COALESCE(SUM(CASE WHEN EVR_CAUSE = 1 THEN COUNT ELSE 0 END), 0) AS C2, COALESCE(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0) AS C3, COALESCE(SUM(CASE WHEN EVR_CAUSE = 13 THEN COUNT ELSE 0 END), 0) AS C4, COALESCE(SUM(CASE WHEN EVR_CAUSE = 4 THEN COUNT ELSE 0 END), 0) AS C5, COALESCE(SUM(CASE WHEN EVR_CAUSE = 5 THEN COUNT ELSE 0 END), 0) AS C6, COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END), 0) AS C7, CASE WHEN COALESCE(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN COUNT ELSE 0 END), 0) = 0 THEN 0 ELSE ROUND(SUM(CASE WHEN EVR_CAUSE IN (13, 4) THEN DURATION ELSE 0 END)::numeric / NULLIF(SUM(CASE WHEN EVR_CAUSE = 3 THEN COUNT ELSE 0 END), 0), 2) END AS C8 FROM IVR_MIS_CUMULATIVE WHERE GEN_TIME BETWEEN TO_TIMESTAMP(''_$fromDate$_'', ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(''_$toDate$_'', ''