INSERT INTO CUMULATION_TABLE (CUMULATION_TABLE_NAME, EVR_TABLE_NAME, CUMULATION_COLUMNS, EVR_TABLE_TYPE, TABLE_ID, DB_USER, DB_PSWD, DB_IP, DB_NAME, DB_SRV, SELECT_QUERY) VALUES('IVR_MIS_CUMULATIVE', 'IVR_EVR_DETAILS', 'COUNT,DURATION', 'D', 2,'<IVR_MIS_DB_USER>', '<IVR_MIS_DB_PASSWORD>', '<IVR_MIS_DB_IP>', '<IVR_MIS_DB_NAME>', 'public','SELECT DATE_TRUNC(''hour'', GEN_TIME) AS GEN_TIME, EVR_EVENT AS EVR_EVENT, EVR_CAUSE AS EVR_CAUSE, EVR_CAUSE AS EVR_REASON, SHORT_CODE, COUNT(*) AS COUNT, SUM(DURATION) AS DURATION FROM <:EVR_TABLE> WHERE GEN_TIME BETWEEN TO_TIMESTAMP(<:startDate>, ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(<:endDate>, ''YYYY-MM-DD HH24:MI:SS'') GROUP BY DATE_TRUNC(''hour'', GEN_TIME), EVR_EVENT, EVR_CAUSE, EVR_REASON, SHORT_CODE LIMIT 200');
INSERT INTO CUMULATION_TABLE
(CUMULATION_TABLE_NAME, EVR_TABLE_NAME, CUMULATION_COLUMNS, EVR_TABLE_TYPE, TABLE_ID, DB_USER, DB_PSWD, DB_IP, DB_NAME, DB_SRV, SELECT_QUERY) VALUES('IVR_MIS_CONTENT_CUMULATIVE', 'IVR_EVR_DETAILS', 'NO_CONTENT_UPLOAD,NO_CONTENT_DELETE,NO_CONTENT_AVAILABLE,NO_CONTENT_BLOCKED,NO_CONTENT_PREVIEW,NO_CONTENT_REJECTED', 'D', 1,'<IVR_MIS_DB_USER>', '<IVR_MIS_DB_PASSWORD>', '<IVR_MIS_DB_IP>', '<IVR_MIS_DB_NAME>','public', 
INSERT INTO CUMULATION_TABLE
(CUMULATION_TABLE_NAME, EVR_TABLE_NAME, CUMULATION_COLUMNS, EVR_TABLE_TYPE, TABLE_ID, DB_USER, DB_PSWD, DB_IP, DB_NAME, DB_SRV, SELECT_QUERY) VALUES('OBD_COMPLETE_MIS_CUMULATIVE','IVR_EVR_DETAILS','TOTAL_COUNT','D','3','<IVR_MIS_DB_USER>', '<IVR_MIS_DB_PASSWORD>', '<IVR_MIS_DB_IP>', '<IVR_MIS_DB_NAME>','public','SELECT DATE_TRUNC(''hour'', A.GEN_TIME) AS GEN_DATE, EXTRACT(HOUR FROM A.GEN_TIME) AS GEN_HOUR, A.EVR_CAUSE, A.EVR_EVENT, A.EVR_REASON, A.CAMP_ID, A.DURATION, B.CLIENT_ID, B.LIST_REC_COUNT, COUNT(*) AS TOTAL_COUNT FROM <:EVR_TABLE> A JOIN OBD_CAMPAIGN_MAST B ON A.CAMP_ID = B.CAMP_ID WHERE A.GEN_TIME BETWEEN TO_TIMESTAMP(<:startDate>, ''YYYY-MM-DD HH24:MI:SS'') AND TO_TIMESTAMP(<:endDate>, ''YYYY-MM-DD HH24:MI:SS'') GROUP BY DATE_TRUNC(''hour'', A.GEN_TIME), EXTRACT(HOUR FROM A.GEN_TIME), A.EVR_CAUSE, A.EVR_EVENT, A.EVR_REASON, A.CAMP_ID, A.DURATION, B.CLIENT_ID, B.LIST_REC_COUNT;');
