'SELECT DATE_TRUNC(''hour'', GEN_TIME) AS GEN_DATE, HOUR(GEN_TIME) AS GEN_HOUR, SHORT_CODE AS PROVIDER_ID, 
SUM(CASE WHEN EVR_EVENT = 1 THEN 1 ELSE 0 END) AS NO_CONTENT_UPLOAD, 
SUM(CASE WHEN EVR_EVENT = 2 THEN 1 ELSE 0 END) AS NO_CONTENT_DELETE, 
SUM(CASE WHEN EVR_EVENT = 3 THEN 1 ELSE 0 END) AS NO_CONTENT_AVAILABLE, 
SUM(CASE WHEN EVR_EVENT = 4 THEN 1 ELSE 0 END) AS NO_CONTENT_BLOCKED, 
SUM(CASE WHEN EVR_EVENT = 5 THEN 1 ELSE 0 END) AS NO_CONTENT_PREVIEW, 
SUM(CASE WHEN EVR_EVENT = 6 THEN 1 ELSE 0 END) AS NO_CONTENT_REJECTED 
FROM <:EVR_TABLE> 
WHERE GEN_TIME BETWEEN TO_TIMESTAMP(<:startDate>, ''YYYY-MM-DD HH24:MI:SS'') 
AND TO_TIMESTAMP(<:endDate>, ''YYYY-MM-DD HH24:MI:SS'') 
GROUP BY DATE_TRUNC(''hour'', GEN_TIME), HOUR(GEN_TIME), SHORT_CODE');

 


COMMIT;
